import java.io.File;
import java.io.FileReader;
import java.io.IOException;

public class CheckedUncheckedComparisonDemo {
    // 1. Checked Exception Demonstration
    // Compiler strictly requires 'throws IOException' or a try-catch block!
    public static void openFileChecked(String filename) throws IOException {
        File file = new File(filename);
        FileReader reader = new FileReader(file); // Might throw FileNotFoundException
        reader.close();
    }

    // 2. Unchecked Exception Demonstration
    // No 'throws' clause required by compiler!
    public static void parseAgeUnchecked(String text) {
        int age = Integer.parseInt(text); // Might throw NumberFormatException
        if (age < 0) {
            throw new IllegalArgumentException("Age cannot be negative"); // Unchecked
        }
        System.out.println("Valid age: " + age);
    }

    public static void main(String[] args) {
        System.out.println("--- 1. Handling Checked Exception ---");
        try {
            openFileChecked("non_existent_config.json");
        } catch (IOException e) {
            System.out.println("Caught checked IOException: " + e.getMessage());
        }

        System.out.println("\n--- 2. Handling Unchecked Exception ---");
        try {
            parseAgeUnchecked("-10");
        } catch (IllegalArgumentException e) {
            System.out.println("Caught unchecked IllegalArgumentException: " + e.getMessage());
        }
    }
}

