            throw new ArithmeticException("Cannot divide by zero");
        }
        return a / b;
    }
    public static void main(String[] args) {
        try {
            divideUnchecked(10, 0);
        } catch (ArithmeticException e) {
            System.out.println("Unchecked caught: " + e.getMessage());
        }
    }
}

