    static String classify(Throwable t) {
        if (t instanceof RuntimeException || t instanceof Error) {
            return "UNCHECKED";
        }
        return "CHECKED";
    }
    public static void main(String[] args) {
        System.out.println("NPE is " + classify(new NullPointerException()));
        System.out.println("Exception is " + classify(new Exception()));
    }
}

